from datetime import datetime
from typing import Optional
from pydantic import BaseModel, ConfigDict


class ClassProbabilities(BaseModel):
    Cataract: float
    Diabetic_Retinopathy: float
    Glaucoma: float
    Normal: float

    model_config = ConfigDict(populate_by_name=True)


class PredictionResponse(BaseModel):
    prediction_id: str
    prediction: str
    confidence: float
    probabilities: dict[str, float]
    model: str
    model_version: str
    gradcam_available: bool
    gradcam_url: Optional[str] = None
    disclaimer: str = (
        "This prediction is generated by an AI/ML model for educational and "
        "research purposes and should not be considered a medical diagnosis. "
        "Consult a qualified eye-care professional for clinical evaluation."
    )


class PredictionHistoryItem(BaseModel):
    model_config = ConfigDict(from_attributes=True)
    id: str
    predicted_class: str
    confidence: float
    model_name: str
    image_path: str
    created_at: datetime


class PredictionDetail(PredictionHistoryItem):
    probabilities: dict[str, float]
    gradcam_path: Optional[str] = None
